import{_ as s,a0 as l,w as a,s as r,I as e,x as n,a1 as u,A as i,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"Ubuntu Linux 的不同安裝類型：服務器 vs 桌面 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu Linux 的不同安裝類型：服務器 vs 桌面 | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu Linux 的不同安裝類型：服務器 vs 桌面 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu Linux 的不同安裝類型：服務器 vs 桌面 | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170821 Linux Installation Types Server Vs. Desktop","title":"Ubuntu Linux 的不同安裝類型：服務器 vs 桌面","tag":"201708","desc":""},"relativePath":"201708/20170821 Linux Installation Types Server Vs. Desktop.md","filePath":"[post].md"}'),m={name:"201708/20170821 Linux Installation Types Server Vs. Desktop.md"};function d(g,t,x,T,b,L){const p=l("Link");return a(),r("div",null,[t[19]||(t[19]=e("h1",{id:"ubuntu-linux-的不同安裝類型-服務器-vs-桌面",tabindex:"-1"},[n("Ubuntu Linux 的不同安裝類型：服務器 vs 桌面 "),e("a",{class:"header-anchor",href:"#ubuntu-linux-的不同安裝類型-服務器-vs-桌面","aria-label":"Permalink to “Ubuntu Linux 的不同安裝類型：服務器 vs 桌面”"},"​")],-1)),t[20]||(t[20]=e("blockquote",null,[e("p",null,"內核是任何 Linux 機器的核心")],-1)),e("p",null,[t[1]||(t[1]=n("之前我已經講了獲取與安裝 Ubuntu Linux，這次我將講桌面和服務器的安裝。兩類安裝都滿足某些需求。不同的安裝包是從 Ubuntu 分開下載的。你可以從 ",-1)),u(p,{href:"https://www.ubuntu.com/download"},{default:i(()=>[...t[0]||(t[0]=[n("Ubuntu.com/downloads",-1)])]),_:1}),t[2]||(t[2]=n(" 選擇你需要的。",-1))]),t[21]||(t[21]=o('<p>無論安裝類型如何，都有一些相似之處。</p><p><img src="http://www.radiomagonline.com/Portals/0/radio-managing-tech-Ubuntu_1.jpg" alt=""></p><p><em>可以從桌面系統圖形用户界面或從服務器系統命令列添加安裝包。</em></p><p>兩者都使用相同的內核和包管理器系統。軟件包管理器系統是預編譯為可在幾乎任何 Ubuntu 系統運行的程序的倉庫。程序分組成包，然後以安裝包進行安裝。安裝包可以從桌面系統圖形用户界面或從服務器系統命令列添加。</p><p>程序安裝使用一個名為 <code>apt-get</code> 的程序。這是一個包管理器系統或程序管理器系統。最終用户只需輸入命令列 <code>apt-get install (package-name)</code>，Ubuntu 就會自動獲取軟件包並進行安裝。</p><p>軟件包通常安裝可以通過手冊頁訪問的文檔的命令（這本身就是一個主題）。它們可以通過輸入 <code>man (command)</code> 來訪問。這將打開一個描述該命令詳細用法的頁面。終端用户還可以 Google 任何的 Linux 命令或安裝包，並找到大量關於它的信息。</p><p>例如，在安裝網絡連接存儲套件後，可以通過命令列、GUI 或使用名為 Webmin 的程序進行管理。Webmin 安裝了一個基於 Web 的管理界面，用於配置大多數 Linux 軟件包，它受到了僅安裝服務器版本的人羣的歡迎，因為它安裝為網頁，不需要 GUI。它還允許遠程管理服務器。</p><p>大多數（如果不是全部）基於 Linux 的軟件包都有專門幫助你如何運行該軟件包的視頻和網頁。只需在 YouTube 上搜索 “Linux Ubuntu NAS”，你就會找到一個指導你如何設置和配置此服務的視頻。還有專門指導 Webmin 的設置和操作的視頻。</p><p>內核是任何 Linux 安裝的核心。由於內核是模組化的，它是非常小的（顧名思義）。我在一個 32MB 的小型閃存上運行 Linux 服務器。我沒有打錯 - 32MB 的空間！Linux 系統使用的大部分空間都是由安裝的軟件包使用的。</p><p><strong>服務器</strong></p><p>服務器安裝 ISO 鏡像是 Ubuntu 提供的最小的下載。它是針對服務器操作優化的操作系統的精簡版本。此版本沒有 GUI。默認情況下，它完全從命令列運行。</p><p>移除 GUI 和其他組件可簡化系統並最大限度地提高性能。最初沒有安裝的必要軟件包可以稍後通過命令列程序包管理器添加。由於沒有 GUI，因此必須從命令列完成所有配置、故障排除和包管理。許多管理員將使用服務器安裝來獲取一個乾淨或最小的系統，然後只添加他們需要的某些包。這包括添加桌面 GUI 系統並製作精簡桌面系統。</p>',12)),e("p",null,[t[4]||(t[4]=n("廣播電台可以使用 Linux 服務器作為 Apache Web 服務器或資料庫服務器。這些是真實需要消耗處理能力的程序，這就是為什麼它們通常使用服務器形式安裝以及沒有 GUI 的原因。SNORT 和 Cacti 是可以在你的 Linux 服務器上運行的其他程序（這兩個應用程序都在上一篇文章中介紹，可以在這裏找到：",-1)),u(p,{href:"http://tinyurl.com/yd8dyegu"},{default:i(()=>[...t[3]||(t[3]=[e("em",null,"http://tinyurl.com/yd8dyegu",-1)])]),_:1}),t[5]||(t[5]=n("）。",-1))]),t[22]||(t[22]=o('<p><strong>桌面</strong></p><p>桌面安裝 ISO 鏡像相當大，並且有多個在服務器安裝 ISO 鏡像上沒有的軟件包。此安裝用於工作站或日常桌面使用。此安裝類型允許自定義安裝包（程序），或者可以選擇默認的桌面配置。</p><p><img src="http://www.radiomagonline.com/Portals/0/radio-managing-tech-Ubuntu_2.jpg" alt=""></p><p><em>桌面安裝 ISO 鏡像相當大，並且有多個在服務器安裝 ISO 鏡像上沒有的軟件包。此安裝包專為工作站或日常桌面使用設計。</em></p><p>軟件包通過 apt-get 包管理器系統安裝，就像服務器安裝一樣。兩者之間的區別在於，在桌面安裝中，apt-get 包管理器具有不錯的 GUI 前端。這允許通過點擊鼠標輕鬆地從系統安裝或刪除軟件包！桌面安裝將設置一個 GUI 以及許多與桌面操作系統相關的軟件包。</p><p><img src="http://www.radiomagonline.com/Portals/0/radio-managing-tech-Ubuntu_3.jpg" alt=""></p><p><em>通過 apt-get 包管理器系統安裝軟件包，就像服務器安裝一樣。兩者之間的區別在於，在桌面安裝中，apt-get 包管理器具有不錯的 GUI 前端。</em>*</p><p>這個系統安裝後隨時可用，可以很好的替代你的 Windows 或 Mac 台式機。它有很多包，包括 Office 套件和 Web 瀏覽器。</p><p>Linux 是一個成熟而強大的操作系統。無論哪種安裝類型，它都可以配置為適合幾乎所有需要。從功能強大的資料庫服務器到用於網頁瀏覽和寫信給奶奶的基本台式機操作系統，天空有極限，而可用的安裝包幾乎是不竭的。如果你遇到一個需要計算機化解決方案的問題，Linux 可能會提供免費或低成本的軟件來解決該問題。</p><p>通過提供兩個安裝版本，Ubuntu 做得很好，這讓人們開始朝着正確的方向前進。</p><p><em>Cottingham 是前無線電總工程師，現在從事流媒體工作。</em></p><hr>',12)),e("p",null,[t[7]||(t[7]=n("via: ",-1)),u(p,{href:"http://www.radiomagonline.com/deep-dig/0005/linux-installation-types-server-vs-desktop/39123"},{default:i(()=>[...t[6]||(t[6]=[n("http://www.radiomagonline.com/deep-dig/0005/linux-installation-types-server-vs-desktop/39123",-1)])]),_:1})]),e("p",null,[t[11]||(t[11]=n("作者：",-1)),u(p,{href:"http://www.radiomagonline.com/author/chris-cottingham"},{default:i(()=>[...t[8]||(t[8]=[n("Chris Cottingham",-1)])]),_:1}),t[12]||(t[12]=n(" 譯者：",-1)),u(p,{href:"https://github.com/geekpi"},{default:i(()=>[...t[9]||(t[9]=[n("geekpi",-1)])]),_:1}),t[13]||(t[13]=n(" 校對：",-1)),u(p,{href:"https://github.com/wxy"},{default:i(()=>[...t[10]||(t[10]=[n("wxy",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=n("本文由 ",-1)),u(p,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[14]||(t[14]=[n("LCTT",-1)])]),_:1}),t[17]||(t[17]=n(" 原創編譯，",-1)),u(p,{href:"https://linux.cn/"},{default:i(()=>[...t[15]||(t[15]=[n("Linux中國",-1)])]),_:1}),t[18]||(t[18]=n(" 榮譽推出",-1))])])}const I=s(m,[["render",d]]);export{U as __pageData,I as default};
